window.OLAYLAR_AVMAC_C_1029 = [{"bolge":2,"t":"1867-06-08","b":"I. Franz Joseph Budapeşte'de Macaristan kralı olarak taç giydi — ikili monarşi (Avusturya-Macaristan) tamamlandı","tur":"siyaset","onem":4,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"I. Franz Joseph, Gyula Andrássy","d":"1867 Uzlaşması (Ausgleich) Macaristan'a iç işlerinde ayrı hükûmet ve parlamento tanıdı; dış politika, ordu ve ortak maliye ortak kaldı. Franz Joseph 8 Haziran 1867'de Macaristan kralı olarak taçlandırıldı.","kaynak":"Szilágyi Sándor, A Magyar Nemzet Története (mek.oszk.hu/00800/00893/html/doc/c400581.htm); Szász Zoltán, A '67-es kiegyezési rendszer (europainstitut.hu, 2017) — ikinci kaynak — «1867 június 8-ikán a koronázás megtörtént»"},{"bolge":3,"t":"1918-11-11","b":"İmparator I. Karl devlet işlerine katılmaktan vazgeçtiğini bildirdi (Avusturya için)","tur":"hukumdar","onem":4,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Viyana","yer_id":"Viyana","kisiler":"İmparator I. Karl","d":"Karl, Avusturya'daki devlet işlerine katılmaktan vazgeçtiğini 11 Kasım 1918'de bildirdi; tahttan açıkça feragat etmedi. Ertesi gün Geçici Millî Meclis cumhuriyet biçimini ilân etti. Macaristan için ayrı bildiri (Eckartsau) 13 Kasım tarihlidir.","kaynak":"Parlament Österreich 'Geburt der Republik' (parlament.gv.at/verstehen/historisches/1918-1945/geburt-der-republik) · TDV avusturya (18 Kasım)"},{"bolge":2,"t":"1918-11-13","b":"Karl'ın Eckartsau bildirisi: Macaristan devlet işlerine katılmaktan vazgeçti, memurları bağlılık yeminlerinden çözdü","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"IV. Károly (I. Karl), Mihály Károlyi","d":"Eckartsau'da yazılan bildiri 13 Kasım 1918 tarihlidir; Budapeşte'de 14 Kasım'da yayımlandı. Karl yalnız egemenlik haklarının kullanımından vazgeçti, 'tahttan feragat' sözcüğünü kullanmadı. Haritada Macaristan zincirleri 11 Kasım'da, künyedeki Halk Cumhuriyeti ilânı 16 Kasım'da döner; 13 Kasım bu iki gün arasındaki hukukî halkadır.","kaynak":"https://www.archontology.org/nations/hungary/karoly4.php · https://theorangefiles.hu/the-first-hungarian-republic/ · https://openaccess.ludovika.hu/nke/catalog/download/15/34/136?inline=1"},{"bolge":2,"t":"1918-11-16","b":"Macar Millî Konseyi Macaristan Halk Cumhuriyeti'ni ilân etti — Károlyi önderliğinde monarşi resmen kalktı","tur":"kurulus","onem":4,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Mihály Károlyi","d":"Károlyi 31 Ekim 1918'de (Pat Çiçeği Devrimi) Karl tarafından başbakan atanmıştı. 16 Kasım 1918'de Millî Konsey ve hükûmet Halk Cumhuriyeti'ni ilân etti; 11 Ocak 1919'da Károlyi geçici cumhurbaşkanı oldu. macaristan-naiplik ve macaristan-halk-cumhuriyeti künyeleri bu günden başlar. Bu olayla Aquincum-Óbuda-Pest, Estergon, Eğri, Segedin (Szeged), Debrecen, Varad ve Yukarı Macaristan dahil Macaristan Krallığı'nın Hırvatistan dışındaki şehirleri Macaristan Halk Cumhuriyeti'ne geçti.","kaynak":"TDV macaristan (31 Ekim 1918; cumhuriyet günü yok) · https://theorangefiles.hu/the-first-hungarian-republic/ · https://www.archontology.org/nations/hungary/karoly4.php · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Vizi László Tamás, 'Az első magyar köztársaság születése: Budapest 1918. november 16.', Acta Scientiarum Socialium 48 (2018), s. 59-67, DOI 10.33566/asc.2755, s. 63 (néphatározat metni; KN XLI. kötet 457) ; çelişki için Hrvatski sabor, 'Hrvatski građanski sabor 1848.–1918.' (https://www.sabor.hr/sites/default/files/uploads/inline-files/PDF3.pdf) ; N. Stančić, HAZU Dan neovisnosti 2011 konuşması (https://historiografija.hr/wp-content/uploads/2026/01/2011-HAZU-Dan-neovisnosti_Stancic.pdf) ; TDV 'Macaristan' md.: '31 Ekim 1918'de “pat çiçeği devrimi” neticesinde ... Károlyi başbakan oldu' (cumhuriyet günü yok)"},{"bolge":2,"t":"1919-03-21","b":"Béla Kun hükûmeti Macar Sovyet Cumhuriyeti'ni ilân etti","tur":"siyaset","onem":4,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Béla Kun, Sándor Garbai","d":"Antant'ın Vix notası (20 Mart) Macar birliklerinin geri çekilmesini isteyince Károlyi hükûmeti çekildi; Sosyal Demokratlarla birleşen komünistler 21 Mart 1919'da Sovyet Cumhuriyeti'ni kurdu. Cumhuriyet 133 gün (TDV: 121 gün diyen ifade de var) sürdü; harita bu dönemde macaristan-naiplik kimliğini kullanır.","kaynak":"Britannica 'Béla Kun' (21 Mart 1919 / 1 Ağustos 1919) · TDV macaristan (121 gün)"},{"bolge":1,"t":"1919-08-04","b":"Romanya ordusu Budapeşte'ye girdi — Kun'un kaçışının üç gün sonrası","tur":"isgal","onem":3,"dunya":1,"kapsam":"dis","etiket":["isgal","konu-askeri"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Béla Kun","d":"Kun ve çevresi 1 Ağustos 1919'da Avusturya'ya kaçtı; Romanya ordusu üç gün sonra Budapeşte'yi işgal etti ve Kasım 1919 ortasına kadar şehirde kaldı.","kaynak":"TDV macaristan (Kun'dan üç gün sonra) · https://theorangefiles.hu/the-horthy-era-1920-1944-long/"},{"bolge":1,"t":"1919-11-16","b":"Horthy'nin Millî Ordusu Budapeşte'ye girdi — Romanya çekildikten sonra karşı-devrim iktidarı aldı","tur":"siyaset","onem":3,"dunya":1,"kapsam":"dis","etiket":["siyaset","konu-askeri"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Miklós Horthy","d":"Romanya birlikleri 14 Kasım 1919'da Budapeşte'den ayrıldı; Horthy komutasındaki Millî Ordu 16 Kasım 1919'da şehre girdi. Horthy'nin 1 Mart 1920'de naipliğe getirilmesinin yolu böylece açıldı.","kaynak":"https://theorangefiles.hu/the-horthy-era-1920-1944-long/ · https://www.hungarianconservative.com/articles/culture_society/horthy_march-on-budapest_white-horse_regent/"},{"bolge":1,"t":"1921-10-13","b":"Venedik Protokolü — Macaristan Burgenland'ı Avusturya'ya devretmeyi, Sopron'da plebisiti kabul etti","tur":"antlasma","onem":3,"dunya":1,"kapsam":"dis","etiket":["antlasma","toprak-kazanc","konu-diplomasi"],"yer":"Venedik · Eisenstadt","yer_id":"Eisenstadt (Kismarton)","kisiler":"—","d":"İtalya'nın arabuluculuğunda 11-13 Ekim 1921'de yapılan görüşmelerin sonunda Macaristan, birliklerini çekip Burgenland'ı Avusturya'ya bırakmayı; Avusturya ise Sopron ve çevresindeki sekiz köyde plebisit yapmayı kabul etti. 28 Ağustos 1921'deki ilk Avusturya girişimi Macar çeteleri yüzünden başarısız olmuştu (jandarma 10 Eylül'de eski sınıra döndü).","kaynak":"Cambridge, Nationalities Papers, 'Disputed land: Italy, the Military Inter-Allied Commission and the plebiscite of Sopron' · AEIOU Austria-Forum 'Venediger Protokoll' (13 Ekim 1921)"},{"bolge":1,"t":"1921-12-14","b":"Sopron plebisiti başladı — oyların yaklaşık yüzde 65'i Macaristan'dan yana çıktı","tur":"siyaset","onem":3,"dunya":1,"kapsam":"dis","etiket":["siyaset","toprak-kazanc","konu-siyasi"],"yer":"Sopron","yer_id":"Sopron","kisiler":"Müttefik Generaller Komisyonu","d":"14-15 Aralık 1921'de Sopron ve Brennbergbánya, 16 Aralık'ta çevredeki sekiz köy oy kullandı. Şehirde Macaristan, köylerin çoğunda Avusturya önde çıktı; toplamda Macaristan yaklaşık yüzde 65. Müttefik Generaller Komisyonu bölgeyi 1 Ocak 1922'de Macaristan'a devretti (haritadaki Sopron zinciri Macar kalır).","kaynak":"Cambridge, Nationalities Papers (Sopron plebisiti) · https://ww1.habsburger.net/en/node/6227 · https://hungarytoday.hu/sopron-referendum-1921-100th-anniversary-100-years-ago-austria-hungary/"},{"bolge":2,"t":"1938-03-12","b":"Alman birlikleri Avusturya'ya girdi — Anschluss yasası ertesi gün çıkarıldı","tur":"isgal","onem":4,"dunya":3,"kapsam":"dis","etiket":["isgal","konu-askeri"],"yer":"Viyana","yer_id":"Viyana","kisiler":"Adolf Hitler, Kurt Schuschnigg","d":"Schuschnigg'in plebisit çağrısı Hitler'i müdahaleye yöneltti; Alman ordusu 12 Mart 1938'de Avusturya'ya girdi, 13 Mart'ta Avusturya'nın Reich'a katılması yasalaştı (haritada zincirler 13 Mart'ta döner).","kaynak":"TDV avusturya (12 Mart 1938 işgal) · AVALON Yale imt/judaus (13 Mart 1938 yasa)"},{"bolge":2,"t":"1944-03-19","b":"Almanya Macaristan'ı işgal etti (Margarethe Harekâtı)","tur":"isgal","onem":4,"dunya":2,"kapsam":"dis","etiket":["isgal","konu-askeri"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Miklós Horthy, Döme Sztójay","d":"Macaristan'ın Müttefiklerle ayrı barış arayışı üzerine Alman birlikleri 19 Mart 1944'te ülkeyi işgal etti; Sztójay hükûmeti kuruldu ve Macar Yahudilerinin sürgünü başladı. Horthy 15 Ekim 1944'te ateşkes ilânı girişimiyle devrildi, Ok-Haç iktidarı aldı.","kaynak":"TDV macaristan ('19 Mart 1944’te Almanlar devreye girdiler') · USHMM (19 Mart 1944, devletler.js macaristan-naiplik kaydı)"},{"bolge":1,"t":"1945-04-04","b":"Sovyet ordusu Macaristan'ı Alman denetiminden çıkardı — son Alman birlikleri ülkeden atıldı","tur":"isgal","onem":4,"dunya":2,"kapsam":"dis","etiket":["isgal","konu-askeri"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Rus ordusu","d":"Macaristan'a giren Sovyet ordusu 4 Nisan 1945'te Alman etkisini sona erdirdi. Macaristan 1946'ya kadar Müttefik (Sovyet) Kontrol Komisyonu denetiminde kaldı; cumhuriyet 1 Şubat 1946'da ilân edildi.","kaynak":"TDV macaristan ('Macaristan’a giren Rus ordusu 4 Nisan 1945’te Alman etkisini sona erdirdi')"},{"bolge":1,"t":"1945-04-13","b":"Kızıl Ordu Viyana'yı ele geçirdi — Viyana Savaşı sona erdi","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["isgal","konu-askeri"],"yer":"Viyana","yer_id":"Viyana","kisiler":"Fyodor Tolbukhin","d":"Kızıl Ordu 5 Nisan 1945'te Viyana'nın batı kenarına ulaştı; 13 Nisan saat 14'te Sovyet komutanlığı çatışmanın bittiğini bildirdi. Renner'in geçici hükûmeti iki hafta sonra, 27 Nisan'da Avusturya'nın bağımsızlığını ilân etti (haritada Viyana zinciri 27 Nisan'da Almanya'dan II. Cumhuriyet'e döner).","kaynak":"ORF Wien 'Befreiung durch die Rote Armee' (wien.orf.at/stories/3300610) · vienna.at 70 Jahre Befreiung · TDV avusturya (27 Nisan 1945)"},{"bolge":1,"t":"1945-07-09","b":"Viyana'nın dört bölgeye ayrılması anlaşması — Batılı müttefikler 1 Eylül'de sektörlerine yerleşti","tur":"antlasma","onem":2,"dunya":1,"kapsam":"dis","etiket":["antlasma","konu-askeri"],"yer":"Viyana","yer_id":"Viyana","kisiler":"ABD, SSCB, Britanya, Fransa","d":"Besatzungszonen ve Viyana şehrinin idaresine ilişkin anlaşma 9 Temmuz 1945 tarihlidir; ABD, Britanya ve Fransa güçleri sektörlerine 1 Eylül 1945'te geldi, Müttefik Konseyi 11 Eylül'de toplandı. Dört güç denetimi 1955'e dek sürdü. Haritada ayrı işgal bölgesi kimliği yoktur (motor dondurma: yeni BOYALAR anahtarı eklenmedi).","kaynak":"Wien Geschichte Wiki 'Alliierte Besatzung' (geschichtewiki.wien.gv.at/Besatzungszeit) · TDV avusturya (1945-1955 dört devlet denetimi)"},{"bolge":1,"t":"1949-08-20","b":"Macaristan Halk Cumhuriyeti anayasası yürürlüğe girdi — Sovyet tipi tek parti rejimi","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Mátyás Rákosi","d":"20 Ağustos 1949 tarihli anayasa Macaristan'ı Halk Cumhuriyeti yaptı. macaristan-halk künyesi (1946-1989) bu iki rejimi tek polity olarak tutar; harita boyası değişmez.","kaynak":"https://doha.mfa.gov.hu/eng/page/the-history-of-hungary (devletler.js macaristan-halk künyesinin kaynağı)"},{"bolge":1,"t":"1955-05-15","b":"Avusturya Devlet Antlaşması Viyana'da imzalandı — dört güç işgali sona eriyor","tur":"antlasma","onem":4,"dunya":3,"kapsam":"dis","etiket":["antlasma","konu-diplomasi"],"yer":"Viyana","yer_id":"Viyana","kisiler":"Leopold Figl, Molotov, Dulles, Macmillan, Pinay","d":"ABD, SSCB, Britanya, Fransa ve Avusturya 15 Mayıs 1955'te Belvedere Sarayı'nda Devlet Antlaşması'nı imzaladı; antlasma 27 Temmuz 1955'te yürürlüğe girdi, son işgal birlikleri 25 Ekim 1955'te ayrıldı, Avusturya Meclisi 26 Ekim 1955'te daimî tarafsızlık anayasa yasasını çıkardı.","kaynak":"TDV avusturya (15 Mayıs 1955; Ekim 1955 çekiliş) · Austria-Forum AEIOU 'Staatsvertrag' · FRUS 1955-57 c.26 belge 13"},{"bolge":2,"t":"1956-10-23","b":"Macar Ayaklanması başladı — Sovyet müdahalesi 4 Kasım'da ayaklanmayı bastırdı","tur":"isyan","onem":4,"dunya":3,"kapsam":"dis","etiket":["isyan","konu-askeri","konu-siyasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"Imre Nagy, János Kádár","d":"Aşırı baskılar 23 Ekim 1956'da halk ayaklanmasına yol açtı; Sovyet birlikleri 4 Kasım'da müdahale etti. Toprak ve sınır değişmedi; rejim Kádár yönetiminde sürdü (macaristan-halk).","kaynak":"TDV macaristan ('23 Ekim 1956 tarihinde halk ayaklanmasına yol açtı' · Sovyet müdahalesi 4 Kasım)"},{"bolge":1,"t":"1995-01-01","b":"Avusturya Avrupa Birliği'ne katıldı","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-diplomasi"],"yer":"Viyana","yer_id":"Viyana","kisiler":"—","d":"Avusturya, İsveç ve Finlandiya'yla birlikte 1 Ocak 1995'te AB üyesi oldu. Devlet ve sınır değişmedi; avusturya-ikinci-cumhuriyet zinciri sürer.","kaynak":"https://european-union.europa.eu/principles-countries-history/country-profiles/austria_en (AB üyelik tarihi)"},{"bolge":1,"t":"2004-05-01","b":"Macaristan Avrupa Birliği'ne katıldı","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["siyaset","konu-diplomasi"],"yer":"Budapeşte","yer_id":"Peşte","kisiler":"—","d":"Macaristan, dokuz ülkeyle birlikte 1 Mayıs 2004'te AB üyesi oldu. Devlet ve sınır değişmedi; macaristan-cumhuriyeti zinciri sürer.","kaynak":"https://european-union.europa.eu/principles-countries-history/country-profiles/hungary_en (AB üyelik tarihi)"}];

